/**
 * One sealed chat message as it goes over the wire. The first three fields are the
 * ratchet header; they are authenticated with the ciphertext.
 */
data class WireMessage (
    /**
     * The sender's current ratchet public key (32 bytes).
     */
    var `ratchetPublic`: kotlin.ByteArray
    , 
    /**
     * Length of the sender's previous sending chain.
     */
    var `previousCount`: kotlin.ULong
    , 
    /**
     * Position of this message in the sending chain.
     */
    var `counter`: kotlin.ULong
    , 
    var `ciphertext`: kotlin.ByteArray
    
){
    

    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeWireMessage: FfiConverterRustBuffer<WireMessage> {
    override fun read(buf: ByteBuffer): WireMessage {
        return WireMessage(
            FfiConverterByteArray.read(buf),
            FfiConverterULong.read(buf),
            FfiConverterULong.read(buf),
            FfiConverterByteArray.read(buf),
        )
    }

    override fun allocationSize(value: WireMessage) = (
            FfiConverterByteArray.allocationSize(value.`ratchetPublic`) +
            FfiConverterULong.allocationSize(value.`previousCount`) +
            FfiConverterULong.allocationSize(value.`counter`) +
            FfiConverterByteArray.allocationSize(value.`ciphertext`)
    )

    override fun write(value: WireMessage, buf: ByteBuffer) {
            FfiConverterByteArray.write(value.`ratchetPublic`, buf)
            FfiConverterULong.write(value.`previousCount`, buf)
            FfiConverterULong.write(value.`counter`, buf)
            FfiConverterByteArray.write(value.`ciphertext`, buf)
    }
}





sealed class FacadeException(message: String): kotlin.Exception(message) {
        
        class Malformed(message: String) : FacadeException(message)
        
        class AuthFailed(message: String) : FacadeException(message)
        
    /**
     * The update is validly signed but not newer than the installed build. It is refused.
     */
        class Downgraded(message: String) : FacadeException(message)
        
        class NoSession(message: String) : FacadeException(message)
        
    /**
     * The peer's pinned key differs from the one offered. The new key is refused.
     * The message names no key; the user must unpin the peer to accept a new one.
     */
        class PinChanged(message: String) : FacadeException(message)
        
    /**
     * The same identity was scanned again for an already-pinned peer.
     */
        class DuplicatePin(message: String) : FacadeException(message)
        
    /**
     * Connecting needs the peer's identity from a scanned QR code first.
     */
        class NotPinned(message: String) : FacadeException(message)
        
    /**
     * The session exists but no network connection is open for it.
     */
        class NoLink(message: String) : FacadeException(message)
        
        class Network(message: String) : FacadeException(message)
        
        class Internal(message: String) : FacadeException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<FacadeException> {
        override fun lift(error_buf: RustBuffer.ByValue): FacadeException = FfiConverterTypeFacadeError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeFacadeError : FfiConverterRustBuffer<FacadeException> {
    override fun read(buf: ByteBuffer): FacadeException {
        
            return when(buf.getInt()) {
            1 -> FacadeException.Malformed(FfiConverterString.read(buf))
            2 -> FacadeException.AuthFailed(FfiConverterString.read(buf))
            3 -> FacadeException.Downgraded(FfiConverterString.read(buf))
            4 -> FacadeException.NoSession(FfiConverterString.read(buf))
            5 -> FacadeException.PinChanged(FfiConverterString.read(buf))
            6 -> FacadeException.DuplicatePin(FfiConverterString.read(buf))
            7 -> FacadeException.NotPinned(FfiConverterString.read(buf))
            8 -> FacadeException.NoLink(FfiConverterString.read(buf))
            9 -> FacadeException.Network(FfiConverterString.read(buf))
            10 -> FacadeException.Internal(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: FacadeException): ULong {
        return 4UL
    }

    override fun write(value: FacadeException, buf: ByteBuffer) {
        when(value) {
            is FacadeException.Malformed -> {
                buf.putInt(1)
                Unit
            }
            is FacadeException.AuthFailed -> {
                buf.putInt(2)
                Unit
            }
            is FacadeException.Downgraded -> {
                buf.putInt(3)
                Unit
            }
            is FacadeException.NoSession -> {
                buf.putInt(4)
                Unit
            }
            is FacadeException.PinChanged -> {
                buf.putInt(5)
                Unit
            }
            is FacadeException.DuplicatePin -> {
                buf.putInt(6)
                Unit
            }
            is FacadeException.NotPinned -> {
                buf.putInt(7)
                Unit
            }
            is FacadeException.NoLink -> {
                buf.putInt(8)
                Unit
            }
            is FacadeException.Network -> {
                buf.putInt(9)
                Unit
            }
            is FacadeException.Internal -> {
                buf.putInt(10)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalString: FfiConverterRustBuffer<kotlin.String?> {
    override fun read(buf: ByteBuffer): kotlin.String? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterString.read(buf)
    }

    override fun allocationSize(value: kotlin.String?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterString.allocationSize(value)
        }
    }

    override fun write(value: kotlin.String?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterString.write(value, buf)
        }
    }
}




